<template><div class="auth-card"><h2>Create your workspace</h2><p class="sub">Start with a clean training operations workspace. No paid AI services required.</p><div class="stepper"><div class="step active"><span class="num">1</span> Account</div><div class="step active"><span class="num">2</span> Organization</div><div class="step"><span class="num">3</span> Ready</div></div><form class="auth-form" @submit.prevent="create"><div class="form-grid"><div class="field"><label>Your name</label><input v-model="form.name" class="input" required></div><div class="field"><label>Work email</label><input v-model="form.email" class="input" type="email" required></div></div><div class="field"><label>Organization name</label><input v-model="form.org" class="input" required></div><div class="form-grid"><div class="field"><label>Country</label><select v-model="form.country" class="select"><option>United Arab Emirates</option><option>India</option><option>Saudi Arabia</option><option>Qatar</option></select></div><div class="field"><label>Timezone</label><select v-model="form.timezone" class="select"><option>Asia/Dubai</option><option>Asia/Kolkata</option></select></div></div><div class="field"><label>Password</label><input v-model="form.password" class="input" type="password" required></div><button class="btn primary" type="submit">Create workspace</button></form><div class="auth-footer">Already have an account? <RouterLink to="/auth/login">Sign in</RouterLink></div></div></template>
